"""ReportLab scientific charts and a viewer of native isolated nose states."""
import json,sys
from pathlib import Path
import numpy as np
from reportlab.graphics.shapes import Drawing,String
from reportlab.graphics.charts.lineplots import LinePlot
from reportlab.graphics import renderSVG
from reportlab.lib import colors
import reportlab

ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'wtc1_simulation_v8/output/aircraft_a13'

def main():
    dst=OUT/'visualisation';assert not dst.exists();dst.mkdir()
    ids=['T25_L0','T25_L1','T25_L2','T25_L3'];labels=['216 triangles','864 triangles','3456 triangles','13824 triangles'];palette=[colors.HexColor(x) for x in ['#bc6541','#ac9440','#469580','#2774ae']]
    fig=Drawing(1100,820);fig.add(String(45,784,'AIRCRAFT-A13 : contact TYPE25, energie et maillage',fontSize=20));fig.add(String(45,753,'Radome isole / facade immobilisee. Geometrie coplanaire, memes materiaux et masse.',fontSize=12));fig.add(String(45,727,'Diagnostic numerique : impact historique, rupture et ecrasement non qualifies.',fontSize=12))
    arrays=[np.load(OUT/'r0'/q/'authoritative_main_history_SI.npz') for q in ids]
    for i,title in enumerate(labels):fig.add(String(45+i*260,696,title,fontSize=12,fillColor=palette[i]))
    panels=[('impulse_Ns','Impulsion X sur la facade (N.s)',1,70,405),('generated_J','Energie generee (kJ)',.001,620,405),('residual_J','Residuel energetique (kJ)',.001,70,80)]
    for key,title,factor,x,y in panels:
        chart=LinePlot();chart.x=x;chart.y=y;chart.width=410;chart.height=220;chart.joinedLines=1;chart.xValueAxis.valueMin=0;chart.xValueAxis.valueMax=.4
        data=[]
        for i,L in enumerate(arrays):
            ix=np.unique(np.r_[np.arange(0,len(L['time_ms']),max(1,len(L['time_ms'])//450)),len(L['time_ms'])-1]);v=L[key][:,0] if key=='impulse_Ns' else L[key];data.append(list(zip(L['time_ms'][ix].tolist(),(v[ix]*factor).tolist())))
            chart.lines[i].strokeColor=palette[i];chart.lines[i].strokeWidth=1.2
        chart.data=data;fig.add(chart);fig.add(String(x,y+245,title,fontSize=14));fig.add(String(x+130,y-35,'Temps physique (ms)',fontSize=11))
    for y,txt in [(315,'Le bilan energetique TYPE25 se ferme.'),(285,'La convergence spatiale reste a verifier dans le rapport.'),(255,'Pas de rupture, ecrasement ou avion complet.'),(225,'Temps natif : 0,4 ms = 0,0004 seconde.'),(195,'Graine : 1102038 ; aucun tirage aleatoire.'),(165,'Aucun terme ajoute pour combler un residu.'),(115,'TYPE25 est un controle numerique non calibre.')]:fig.add(String(610,y,txt,fontSize=12))
    renderSVG.drawToFile(fig,str(dst/'bilans_maillage.svg'))
    case='T25_L2_HALF';d=OUT/'r0'/case;z=np.load(d/'verified_states_SI.npz');g=json.loads((d/'generation.json').read_text());L=np.load(d/'authoritative_main_history_SI.npz');r=json.loads((d/'authoritative_review.json').read_text());used=sorted({n for tr in g['triangles'] for n in tr}|{n for q in g['facade_quads'].values() for tr in q for n in tr});ix=np.array(used)-1;mapping={n:i for i,n in enumerate(used)}
    payload={'case':case,'time_ms':z['time_ms'].tolist(),'x_m':np.round(z['initial_position_m'][ix],7).tolist(),'u_m':np.round(z['displacement_m'][:,ix],8).tolist(),'triangles':[[mapping[n] for n in tr] for tr in g['triangles']],'wall':[[mapping[n] for n in tr] for q in g['facade_quads'].values() for tr in q],'impulse':np.interp(z['time_ms'],L['time_ms'],L['impulse_Ns'][:,0]).tolist(),'residual':np.interp(z['time_ms'],L['time_ms'],L['residual_J']).tolist(),'generated':np.interp(z['time_ms'],L['time_ms'],L['generated_J']).tolist(),'failed':r['failed_checks']}
    html='''<!doctype html><html lang="fr"><meta charset="utf-8"><title>A13 — premier contact du nez</title><style>body{margin:0;background:#111b28;color:#e9eff5;font:16px system-ui}main{max-width:1180px;margin:auto;padding:24px}h1{font-size:26px}p{line-height:1.5}.notice{padding:14px;border-left:4px solid #e7a366;background:#28384c}.controls{display:flex;gap:16px;align-items:center;flex-wrap:wrap;margin:18px 0}button,select{padding:9px;background:#30475d;color:white;border:1px solid #6b859c;border-radius:6px}input{width:300px}canvas{width:100%;height:540px;background:#182635;border-radius:12px}.metrics{display:flex;gap:24px;flex-wrap:wrap;font-size:18px;margin:16px 0}small{color:#b5c9da}a{color:#9dcff5}</style><main><h1>Premier contact du nez — essai isolé A13</h1><p class="notice">Le temps calculé est de <b>0,4 milliseconde</b>, soit 0,0004 seconde. Ce témoin retire le reste de l'avion et immobilise la façade pour étudier le bilan d'énergie. L'impulsion dépend encore du maillage ; la simulation de l'impact historique reste à qualifier.</p><div class="controls"><button id="play">Lecture ralentie</button><input type="range" id="time" min="0" value="0" step="1"><b id="label"></b><select id="view"><option value="close">Premier contact, vue rapprochée</option><option value="full">Radôme entier</option></select><label><input type="checkbox" id="initial" checked style="width:auto"> Position initiale</label></div><canvas id="canvas"></canvas><div class="metrics"><span id="impulse"></span><span id="energy"></span><span id="residual"></span></div><p><small>Vert : radôme déformé ; gris : position initiale ; orange : façade fixe. Déplacements natifs ×1, sans amplification ni trajectoire imposée. Vue X/Z, rotation de 10° pour distinguer les triangles. La lecture est artificiellement ralentie. Aucun écrasement du cœur, délamination ou rupture n'est représenté.</small></p><p><a href="bilans_maillage.svg">Comparer les quatre maillages et leurs bilans</a> · <a href="../rapport_aircraft_a13.md">Rapport complet</a></p></main><script>const D=PAYLOAD;const cv=document.querySelector('#canvas'),ctx=cv.getContext('2d'),slider=document.querySelector('#time');slider.max=D.time_ms.length-1;let playing=false,last=0;function draw(){let b=cv.getBoundingClientRect(),k=+slider.value;cv.width=b.width*devicePixelRatio;cv.height=b.height*devicePixelRatio;ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);ctx.clearRect(0,0,b.width,b.height);let close=document.querySelector('#view').value==='close';let center=close?[.2,0,0]:[.8,0,0],scale=Math.min(b.width/(close?1.3:3.8),b.height/(close?2.1:4.6));function project(p){let x=p[0]-center[0],y=p[1],z=p[2];return[b.width/2+scale*(.985*x+.174*y),b.height/2-scale*z]}function faces(rows,positions,color,alpha){ctx.strokeStyle=color;ctx.globalAlpha=alpha;ctx.lineWidth=.65;for(let tr of rows){if(close&&tr.every(n=>positions[n][0]>.8))continue;ctx.beginPath();tr.forEach((n,i)=>{let p=project(positions[n]);i?ctx.lineTo(...p):ctx.moveTo(...p)});ctx.closePath();ctx.stroke()}}let cur=D.x_m.map((q,i)=>q.map((v,j)=>v+D.u_m[k][i][j]));faces(D.wall,D.x_m,'#eda164',.35);if(document.querySelector('#initial').checked)faces(D.triangles,D.x_m,'#a3afbb',.18);faces(D.triangles,cur,'#55d8b2',.6);ctx.globalAlpha=1;ctx.font='14px system-ui';ctx.fillStyle='#d7e4ef';ctx.fillText('Déplacement ×1 — coordonnées en mètres',20,28);document.querySelector('#label').textContent=D.time_ms[k].toFixed(6)+' ms';document.querySelector('#impulse').textContent='Impulsion X : '+D.impulse[k].toFixed(2)+' N·s';document.querySelector('#energy').textContent='Énergie générée : '+D.generated[k].toFixed(1)+' J';document.querySelector('#residual').textContent='Résidu : '+D.residual[k].toFixed(1)+' J'}slider.oninput=draw;document.querySelector('#view').onchange=draw;document.querySelector('#initial').onchange=draw;window.onresize=draw;document.querySelector('#play').onclick=()=>{playing=!playing;document.querySelector('#play').textContent=playing?'Pause':'Lecture ralentie'};function tick(t){if(playing&&t-last>240){slider.value=(+slider.value+1)%D.time_ms.length;last=t;draw()}requestAnimationFrame(tick)}draw();requestAnimationFrame(tick);</script></html>'''
    html=html.replace('PAYLOAD',json.dumps(payload,separators=(',',':')));(dst/'premier_contact.html').write_text(html,encoding='utf-8')
    js=html.split('<script>')[1].split('</script>')[0];(dst/'viewer_script_for_validation.js').write_text(js,encoding='utf-8')
    assert len(payload['u_m'])==len(payload['time_ms']) and max(n for q in payload['triangles']+payload['wall'] for n in q)<len(ix)
    assert np.all(np.diff(payload['time_ms'])>0) and np.isfinite(np.array(payload['u_m'])).all()
    (dst/'provenance.json').write_text(json.dumps({'case':case,'inputs':[str(d/'verified_states_SI.npz'),str(d/'authoritative_review.json'),str(d/'authoritative_main_history_SI.npz')],'native_displacement_scale':1,'physics_time_unit':'ms','artificial_playback':True,'data_schema_pass':True,'reportlab_version':reportlab.Version,'GUI_render_verified':False,'physical_impact_qualified':False},indent=2),encoding='utf-8')
    print({'viewer':str(dst/'premier_contact.html'),'plot':str(dst/'bilans_maillage.svg')},flush=True)

if __name__=='__main__':main()
